function drawMinimap(w,h){let mw=134,mh=82,x=w-mw-22,y=h-216;if(w<700){mw=90;mh=57;x=w-mw-12;y=286}ctx.save();ctx.fillStyle='#0d1510c9';ctx.strokeStyle='#d7e1d222';ctx.lineWidth=1;ctx.beginPath();ctx.roundRect(x,y,mw,mh,6);ctx.fill();ctx.stroke();let sx=(mw-14)/state.world.w,sy=(mh-14)/state.world.h;for(let l of locations){ctx.fillStyle=l.searched?'#64705e':(Math.hypot(l.x-state.player.x,l.y-state.player.y)<330?'#d6bd82':'#465247');ctx.fillRect(x+7+l.x*sx,y+7+l.y*sy,3,3)}ctx.fillStyle='#c5ef89';ctx.beginPath();ctx.arc(x+7+state.player.x*sx,y+7+state.player.y*sy,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#adbaac';ctx.font='7px monospace';ctx.fillText('PINE RIDGE',x+8,y+mh-5);ctx.restore()}
