function damageFlash(){$('damage-flash').classList.add('on');setTimeout(()=>$('damage-flash').classList.remove('on'),110)}
function loop(now){if(!state.started)return;let dt=Math.min(50,(now-(lastFrame||now))/16.67);lastFrame=now;update(dt);drawWorld();requestAnimationFrame(loop)}
function gameOver(){if(state.over)return;state.over=true;let card=$('modal-card');card.innerHTML=`<div class="intro-eyebrow"><span></span> ${$('day-label').textContent} · ${$('clock-label').textContent}</div><h2>You were lost to the dark.</h2><p>You survived ${state.day} day${state.day===1?'':'s'}, searched ${state.searches} places and defeated ${state.kills} monsters. The forest keeps what it takes.</p><button id="restart-btn">TRY AGAIN</button>`;$('modal-cover').classList.remove('hidden');$('restart-btn').onclick=()=>location.reload()}
