addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);keyMove();if(k==='e')search();if(k===' '||k==='f')attack();if(k==='1'){$('weapon-slot').classList.add('active');$('food-slot').classList.remove('active')}if(k==='2')useQuick();if(k==='i')setPanel('bag');if(k==='escape')togglePause()});addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());keyMove()});
$('start-button').onclick=startGame;$('weapon-slot').onclick=()=>{$('weapon-slot').classList.add('active');$('food-slot').classList.remove('active');showToast(`${state.weapon} ready.`)};$('food-slot').onclick=useQuick;$('touch-search').onclick=search;$('touch-attack').onclick=attack;
$('close-panel').onclick=()=>$('side-panel').classList.remove('open');document.querySelectorAll('.nav-button').forEach(b=>b.onclick=()=>setPanel(b.dataset.panel));$('map-btn').onclick=()=>setPanel('map');$('mission-toggle').onclick=()=>document.querySelector('.mission-card').classList.toggle('collapsed');$('pause-btn').onclick=togglePause;
function togglePause(){if(!state.started)return;state.paused=!state.paused;if(state.paused){let el=document.createElement('div');el.className='pause-screen';el.id='pause-screen';el.innerHTML='<div><div class="intro-eyebrow">THE FOREST IS WAITING</div><h2>Paused</h2><button id="resume-btn">BACK TO THE DARK</button></div>';$('game-shell').appendChild(el);$('resume-btn').onclick=togglePause}else $('pause-screen')?.remove()}
$('side-panel').addEventListener('click',e=>{if(e.target.matches('[data-travel]'))travel(+e.target.dataset.travel)});
const joy=$('joystick'),knob=$('joy-knob');if(joy){let center;joy.addEventListener('pointerdown',e=>{joy.setPointerCapture(e.pointerId);let r=joy.getBoundingClientRect();center={x:r.left+r.width/2,y:r.top+r.height/2};updateJoy(e)});joy.addEventListener('pointermove',e=>{if(center)updateJoy(e)});function updateJoy(e){let dx=e.clientX-center.x,dy=e.clientY-center.y,d=Math.hypot(dx,dy),max=35;if(d>max){dx=dx/d*max;dy=dy/d*max}knob.style.transform=`translate(${dx}px,${dy}px)`;state.joystick={x:dx/max,y:dy/max};keyMove()}function endJoy(){center=null;state.joystick=null;knob.style.transform='';keyMove()}joy.addEventListener('pointerup',endJoy);joy.addEventListener('pointercancel',endJoy)}
initCharacters();updateClock();updateUI();drawWorld();
