function travel(id){let l=places[id],d=Math.hypot(l.x-p.x,l.y-p.y),m=Math.max(8,Math.round(d/20));p.x=l.x-30;p.y=l.y+20;p.hunger=Math.max(0,p.hunger-m*.04);p.thirst=Math.max(0,p.thirst-m*.05);advance(m);$('area-label').textContent=l.name.toUpperCase();$('side-panel').classList.remove('open');show(`Reached ${l.name}. Stay alert.`);update()}
const icons={Food:'◉',Water:'◆',Medicine:'✚',Ammo:'▰',Weapons:'⌁',Wear:'◇',Materials:'▧'};
function panel(name){let panelEl=$('side-panel'),content=$('panel-content');document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('selected',b.dataset.panel===name));if(!name){panelEl.classList.remove('open');return}panelEl.classList.add('open');let titles={bag:['FIELD KIT','Your pack'],map:['FIELD MAP','Places nearby'],craft:['WORKBENCH','Make supplies'],shelter:['SAFE HAVEN','Shelter']};$('panel-kicker').textContent=titles[name][0];$('panel-title').textContent=titles[name][1];if(name==='bag'){content.innerHTML=s.inventory.length?`<div class="inventory-list">${s.inventory.map((it,i)=>`<div class="inventory-item"><span class="item-icon">${icons[it.cat]||'◇'}</span><span><b>${it.name}</b><small>${it.cat} · ×${it.qty}</small></span><button class="item-use" data-use="${i}">${it.cat==='Food'?'EAT':it.cat==='Water'?'DRINK':it.cat==='Medicine'?'USE':''}</button></div>`).join('')}</div>`:'<p class="empty-note">Your pack is empty. Search a marked location.</p>';content.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>useItem(+b.dataset.use))}
if(name==='map')content.innerHTML=`<p class="panel-note">24 known places · tap a marker to travel. Travel takes time and drains supplies.</p><div class="place-list">${places.map(l=>`<button class="place-row" data-place="${l.id}"><span class="place-dot">${l.searched>=2?'✓':'⌖'}</span><span><b>${l.name}</b><small>${l.searched>=2?'PICKED CLEAN':l.searched?'SEARCHED ONCE':'UNSEARCHED'}</small></span><span>→</span></button>`).join('')}</div>`;content.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>travel(+b.dataset.place))
if(name==='craft')content.innerHTML=`<p class="panel-note">Use salvaged materials to make it through the night.</p><div class="recipe-list">${[['Bandage roll','Medicine','Cloth strips ×2','Cloth strips',2],['Wooden club','Weapons','Scrap wood ×3','Scrap wood',3],['Water bottle','Water','Plastic sheet ×1','Plastic sheet',1],['9mm rounds','Ammo','Metal scraps ×2','Metal scraps',2],['Torch','Materials','Scrap wood ×1 + Cloth strips ×1','Scrap wood',1]].map((r,i)=>`<div class="recipe"><div><b>${r[0]}</b><small>${r[2]}</small></div><button data-craft="${i}">MAKE</button></div>`).join('')}</div>`;content.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>craft(+b.dataset.craft))
if(name==='shelter')content.innerHTML=`<div class="shelter-card"><div class="shelter-emblem">⌂</div><h3>${shelter?'Shelter secured':'A roof before night'}</h3><p>${shelter?'Your shelter is standing. Rest here to recover and survive the night.':'Build a shelter to protect yourself. Requires 6 Scrap wood and 4 other materials.'}</p><div class="shelter-requirements"><span>Scrap wood <b>${Math.min(6,qty('Materials')?s.inventory.filter(i=>i.name==='Scrap wood').reduce((a,i)=>a+i.qty,0):0)} / 6</b></span><span>Other materials <b>${Math.min(4,otherMaterials())} / 4</b></span></div><button class="build-button" id="build-shelter">${shelter?'REST & RECOVER':'BUILD SHELTER'}</button></div>`;$('build-shelter')?.addEventListener('click',buildShelter)}
function otherMaterials(){return s.inventory.filter(i=>i.cat==='Materials'&&i.name!=='Scrap wood').reduce((a,i)=>a+i.qty,0)}
function useItem(i){let it=s.inventory[i];if(!it)return;if(it.cat==='Food'){it.qty--;p.hunger=Math.min(100,p.hunger+32);p.sanity=Math.min(100,p.sanity+3)}else if(it.cat==='Water'){it.qty--;p.thirst=Math.min(100,p.thirst+40)}else if(it.cat==='Medicine'){it.qty--;p.hp=Math.min(chars[s.sel].hp,p.hp+35);show(`Used ${it.name}.`)}else return show('That item cannot be used right now.');if(!it.qty)s.inventory.splice(i,1);update();panel('bag')}
